 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    points = {v: [(r, c) for r in range(h) for c in range(w) if grid[r][c] == v]
              for v in (1, 6)}

    # Draw finite 45-degree segments between matching markers.
    one_segments = []
    for color in (1, 6):
        pts = points[color]
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i+1:]:
                dr, dc = r2-r1, c2-c1
                if abs(dr) == abs(dc) and dr != 0:
                    sr, sc = (1 if dr > 0 else -1), (1 if dc > 0 else -1)
                    for k in range(abs(dr)+1):
                        r, c = r1+sr*k, c1+sc*k
                        out[r][c] = color
                    if color == 1:
                        one_segments.append((r1,c1,r2,c2))

    # A 6 marker on a drawn 1 diagonal supplies its crossing diagonal.
    for r, c in points[6]:
        on_one = any(abs(r-r1) == abs(c-c1) and
                     (r-r1)*(r2-r1) >= 0 and
                     abs(r-r1) <= abs(r2-r1) and
                     (c-c1)*(c2-c1) >= 0 and
                     abs(c-c1) <= abs(c2-c1)
                     for r1,c1,r2,c2 in one_segments)
        if on_one:
            # perpendicular diagonal through the marker, clipped to the canvas
            for rr in range(h):
                for cc in (c + (rr-r), c - (rr-r)):
                    if 0 <= cc < w:
                        out[rr][cc] = 6
    return out
